; Sound effect requests: three voice slots with priorities, and silence
; $2509-$2583

; Requests sound effect Y ($80-$8E). Sets SIGVOL to $15 (volume 5, low-pass filter mode bit), then stores Y
; in the first free voice slot of the sound driver (sfx_voice1_state, sfx_voice2_state, sfx_voice3_state;
; 0 = free) and its priority from sound_priority_table,(Y AND $0F) in voice1/2/3_sound_priority.
; When all three slots are busy, the first slot whose priority is not above the new one is replaced;
; otherwise the request is dropped. Changes A and X.
; Sounds: $80 step, $81 Yamo pose, $84 flying kick, $85 punch or strike swing, $86 and $87 hits,
; others from the room and hazard code.
play_sound
        lda #$15                        ; volume 5, low-pass filter mode
        sta SIGVOL
        lda sfx_voice1_state            ; voice slot 1 of the sound driver
        bne play_sound_try_slot2
play_sound_slot1
        sty sfx_voice1_state
        tya
        and #$0f
        tax
        lda sound_priority_table,x
        sta voice1_sound_priority
        rts
play_sound_try_slot2
        lda sfx_voice2_state            ; voice slot 2 of the sound driver
        bne play_sound_try_slot3
play_sound_slot2
        sty sfx_voice2_state
        tya
        and #$0f
        tax
        lda sound_priority_table,x
        sta voice2_sound_priority
        rts
play_sound_try_slot3
        lda sfx_voice3_state            ; voice slot 3 of the sound driver
        bne play_sound_by_priority
play_sound_slot3
        sty sfx_voice3_state
        tya
        and #$0f
        tax
        lda sound_priority_table,x
        sta voice3_sound_priority
        rts
; All slots busy: replace the first slot whose priority is lower than or equal to the new one.
play_sound_by_priority
        tya
        and #$0f
        tax
        lda sound_priority_table,x
        cmp voice1_sound_priority
        bcs play_sound_slot1
        cmp voice2_sound_priority
        bcs play_sound_slot2
        cmp voice3_sound_priority
        bcs play_sound_slot3
        rts
; Frees the three voice slots of the sound driver (sfx_voice1_state, sfx_voice2_state, sfx_voice3_state = 0) and writes 0 to the SID
; addresses $D400-$D420, which silences all voices and sets the volume to 0.
; Called by lose_fall, show_title_screen, init_game_variables, show_player_screen and draw_room.
stop_all_sounds
        lda #$00
        sta sfx_voice1_state
        sta sfx_voice2_state
        sta sfx_voice3_state
        ldx #$20
stop_all_sounds_loop
        sta FRELO1,x                    ; 33 bytes: $D41D-$D41F are unused SID addresses, $D420 mirrors FRELO1
        dex
        bpl stop_all_sounds_loop
        rts
; Priority of each sound effect, 1 byte, indexed by sound number & $0F ($80-$8E). A higher value
; replaces a lower one when all voices are busy. Index $0F would read voice1_sound_priority.
sound_priority_table
        !byte $0b,$0c,$0a,$00,$08,$07,$09,$06
        !byte $00,$00,$01,$02,$03,$04,$05
; Priority of the sound in each voice slot of the sound driver (slots 1, 2, 3), written by play_sound.
voice1_sound_priority
        !byte $00
voice2_sound_priority
        !byte $00
voice3_sound_priority
        !byte $00
